const nodeTypes: NodeTypes = {
  cmv: CmvRootNode,
  ficha: FichaBaseNode,
  cmvItem: CmvItemNode,
  insumo: InsumoNode,
  nf: NFNode,
};

// ---------------------------------------------------------------------------
// INNER COMPONENT (usa useReactFlow())
// ---------------------------------------------------------------------------

function CmvConfiguratorInner() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const cmvIdParam = searchParams.get('focus');
  const cmvId =
    cmvIdParam !== null && cmvIdParam !== ''
      ? parseInt(cmvIdParam, 10)
      : null;

  const {
    loading,
    cmv,
    fichaData,
    items,
    embalagens,
    nfEmbalagemItems,
    positions,
    savePosition,
    refetch,
  } = useCmvGraph(cmvId);

  const { fitView } = useReactFlow();
  const queryClient = useQueryClient();
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // ── Detail panel (Sheet) state ──────────────────────────────────────────
  const [selectedItemData, setSelectedItemData] =
    useState<RawCmvItem | null>(null);
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editPreco, setEditPreco] = useState('');
  const [editObs, setEditObs] = useState('');
  const [editFonteCusto, setEditFonteCusto] = useState<FonteCusto>('fixo');
  const [editNfItemId, setEditNfItemId] = useState('');
  const [editNfOpen, setEditNfOpen] = useState(false);
  const [editNfSearch, setEditNfSearch] = useState('');
  const [editUnidadesPorEmbalagem, setEditUnidadesPorEmbalagem] =
    useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // ── Add Item Dialog state ───────────────────────────────────────────────
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [newTipo, setNewTipo] = useState<TipoItem>('embalagem');
  // embalagem
  const [newEmbalagemId, setNewEmbalagemId] = useState('');
  const [newEmbalagemOpen, setNewEmbalagemOpen] = useState(false);
  const [newEmbalagemSearch, setNewEmbalagemSearch] = useState('');
  const [newFonteCusto, setNewFonteCusto] = useState<FonteCusto>('nf');
  const [newNfItemId, setNewNfItemId] = useState('');
  const [newNfOpen, setNewNfOpen] = useState(false);
  const [newNfSearch, setNewNfSearch] = useState('');
  const [newUnidadesPorEmbalagem, setNewUnidadesPorEmbalagem] = useState('');
  const [newPrecoFixo, setNewPrecoFixo] = useState('');
  const [newQty, setNewQty] = useState('1');
  const [newUnit, setNewUnit] = useState('un');
  // outro
  const [newObs, setNewObs] = useState('');
  const [newPrecoOutro, setNewPrecoOutro] = useState('');
  const [isAddSaving, setIsAddSaving] = useState(false);

  // ── Derived values for dialog ───────────────────────────────────────────
  const selectedEmbalagem = useMemo(
    () =>
      newEmbalagemId
        ? embalagens.find((e) => String(e.id) === newEmbalagemId) ?? null
        : null,
    [newEmbalagemId, embalagens],
  );

  const filteredEmbalagens = useMemo(
    () =>
      embalagens.filter((e) =>
        e.nome.toLowerCase().includes(newEmbalagemSearch.toLowerCase()),
      ),
    [embalagens, newEmbalagemSearch],
  );

  // pré-filtro inteligente de NF quando embalagem selecionada
  const smartNfList = useMemo(() => {
    if (!selectedEmbalagem) return nfEmbalagemItems;
    const keywords = selectedEmbalagem.nome
      .toLowerCase()
      .split(/\s+/)
      .filter((w) => w.length > 2);
    const smart = nfEmbalagemItems.filter(
      (i) =>
        i.nome_produto &&
        keywords.some((kw) => i.nome_produto!.toLowerCase().includes(kw)),
    );
    return smart.length > 0 ? smart : nfEmbalagemItems;
  }, [selectedEmbalagem, nfEmbalagemItems]);

  const filteredNfItems = useMemo(() => {
    const base = newNfSearch ? nfEmbalagemItems : smartNfList;
    if (!newNfSearch) return base;
    const q = newNfSearch.toLowerCase();
    return nfEmbalagemItems.filter(
      (i) =>
        i.nome_produto?.toLowerCase().includes(q) ||
        i.fornecedor?.toLowerCase().includes(q) ||
        i.numero_nota?.toLowerCase().includes(q),
    );
  }, [newNfSearch, nfEmbalagemItems, smartNfList]);

  const nfCustoHint = useMemo((): number | null => {
    if (newFonteCusto !== 'nf' || !newNfItemId || !newUnidadesPorEmbalagem)
      return null;
    const item = nfEmbalagemItems.find((i) => String(i.id) === newNfItemId);
    const units = parseFloat(newUnidadesPorEmbalagem);
    if (!item || !item.valor_unitario || !units || units <= 0) return null;
    return item.valor_unitario / units;
  }, [newFonteCusto, newNfItemId, newUnidadesPorEmbalagem, nfEmbalagemItems]);

  // Edit NF
  const filteredEditNfItems = useMemo(() => {
    if (!editNfSearch) return nfEmbalagemItems;
    const q = editNfSearch.toLowerCase();
    return nfEmbalagemItems.filter(
      (i) =>
        i.nome_produto?.toLowerCase().includes(q) ||
        i.fornecedor?.toLowerCase().includes(q) ||
        i.numero_nota?.toLowerCase().includes(q),
    );
  }, [editNfSearch, nfEmbalagemItems]);

  const editNfCustoHint = useMemo((): number | null => {
    if (
      editFonteCusto !== 'nf' ||
      !editNfItemId ||
      !editUnidadesPorEmbalagem
    )
      return null;
    const item = nfEmbalagemItems.find(
      (i) => String(i.id) === editNfItemId,
    );
    const units = parseFloat(editUnidadesPorEmbalagem);
    if (!item || !item.valor_unitario || !units || units <= 0) return null;
    return item.valor_unitario / units;
  }, [
    editFonteCusto,
    editNfItemId,
    editUnidadesPorEmbalagem,
    nfEmbalagemItems,
  ]);

  // ── Cost breakdown ──────────────────────────────────────────────────────
  const { custoFichaUnitario, custoEmbalagens, custoAvulsos, custoTotal } =
    useMemo(() => {
      const fichaUnitario = fichaData
        ? (fichaData.custo_calculado ?? 0) /
          Math.max(1, fichaData.rendimento_quantidade)
        : 0;
      const embalagensTotal = items
        .filter((i) => i.tipo === 'embalagem')
        .reduce((s, i) => s + (i.custo_calculado ?? 0), 0);
      const avulsosTotal = items
        .filter((i) => i.tipo === 'outro')
        .reduce((s, i) => s + (i.custo_calculado ?? 0), 0);
      const total = cmv?.custo_calculado ?? 0;
      return {
        custoFichaUnitario: fichaUnitario,
        custoEmbalagens: embalagensTotal,
        custoAvulsos: avulsosTotal,
        custoTotal: total,
      };
    }, [items, cmv, fichaData]);

  // ── Build graph ─────────────────────────────────────────────────────────
  const buildGraph = useCallback(() => {
    if (!cmv) return;

    const newNodes: Node[] = [];
    const newEdges: Edge[] = [];

    const rootId = cmvNodeId(cmv.id);

    // Root node
    newNodes.push({
      id: rootId,
      type: 'cmv',
      data: {
        nome: cmv.nome,
        custo: cmv.custo_calculado,
        status: cmv.status,
        kind: 'cmv',
      } as Record<string, unknown>,
      position: positions.get(rootId) ?? { x: 800, y: 300 },
    });

    // Ficha base node
    if (fichaData) {
      const fId = fichaNodeId(fichaData.id);
      const rendQty = fichaData.rendimento_quantidade || 1;
      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;

      newNodes.push({
        id: fId,
        type: 'ficha',
        data: {
          nome: fichaData.nome,
          custoUnitario,
          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
          kind: 'ficha',
        } as Record<string, unknown>,
        position: positions.get(fId) ?? { x: 400, y: 300 },
      });

      newEdges.push({
        id: `e-${fId}-${rootId}`,
        source: fId,
        target: rootId,
        animated: true,
        style: { stroke: '#F59E0B', strokeWidth: 3 },
      });
    }

    // Item nodes
    const addedInsumoIds = new Set<number>();

    items.forEach((item, idx) => {
      const itemId = `item_${item.id}`;
      const label =
        item.produtoMaster?.nome ??
        item.insumo?.nome ??
        item.observacao ??
        `Item ${idx + 1}`;

      newNodes.push({
        id: itemId,
        type: 'cmvItem',
        data: {
          tipo: item.tipo as TipoItem,
          quantidade: item.quantidade,
          unidade: item.unidade,
          custo: item.custo_calculado,
          label,
          kind: 'cmvItem',
          _rawItemId: item.id,
        } as Record<string, unknown>,
        position:
          positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
      });

      newEdges.push({
        id: `e-${itemId}-${rootId}`,
        source: itemId,
        target: rootId,
        style: { stroke: '#52525b', strokeWidth: 2 },
      });

      // Legado: insumo vinculado ao item
      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
        addedInsumoIds.add(item.insumo_id);
        const insId = insumoNodeId(item.insumo_id);

        newNodes.push({
          id: insId,
          type: 'insumo',
          data: {
            nome: item.insumo?.nome ?? 'Insumo',
            preco: item.insumo?.preco_custo ?? null,
            unidade: item.insumo?.unidade_compra ?? 'un',
            kind: 'insumo',
          } as Record<string, unknown>,
          position:
            positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
        });

        newEdges.push({
          id: `e-${insId}-${itemId}`,
          source: insId,
          target: itemId,
          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
        });
      }
    });

    // NF nodes para embalagens com NF travada
    const addedNfNodeIds = new Set<number>();
    items.forEach((item) => {
      if (
        item.nf_item_id &&
        item.nfItem &&
        !addedNfNodeIds.has(item.nf_item_id)
      ) {
        addedNfNodeIds.add(item.nf_item_id);
        const nfId = nfNodeId(item.nf_item_id);
        newNodes.push({
          id: nfId,
          type: 'nf',
          data: {
            fornecedor: item.nfItem.fornecedor ?? 'Fornecedor',
            numero: item.nfItem.numero_nota,
            valor: item.nfItem.valor_unitario,
            kind: 'nf',
          } as Record<string, unknown>,
          position: positions.get(nfId) ?? { x: 50, y: 50 },
        });
      }
    });

    // Edges NF → cmvItem
    items.forEach((item) => {
      if (item.nf_item_id && item.nfItem) {
        const nfId = nfNodeId(item.nf_item_id);
        const itemId = `item_${item.id}`;
        newEdges.push({
          id: `e-${nfId}-${itemId}`,
          source: nfId,
          target: itemId,
          style: {
            stroke: '#22d3ee',
            strokeWidth: 1.5,
            strokeDasharray: '4 2',
          },
        });
      }
    });

    // Apply dagre layout for nodes without saved positions
    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
    if (!hasAllPositions && newNodes.length > 0) {
      const laid = layoutGraph(newNodes, newEdges, 'LR');
      setNodes(laid);
    } else {
      setNodes(newNodes);
    }
    setEdges(newEdges);

    setTimeout(() => {
      fitView({ padding: 0.12, duration: 400 });
    }, 80);
  }, [cmv, fichaData, items, positions, fitView, setNodes, setEdges]);

  useEffect(() => {
    if (!loading) {
      buildGraph();
    }
  }, [loading, buildGraph]);

  // ── Initialize edit panel when item selected ────────────────────────────
  useEffect(() => {
    if (!selectedItemData) return;
    const found = items.find((i) => i.id === selectedItemData.id);
    if (!found) {
      setSelectedItemData(null);
      return;
    }
    setEditQty(String(found.quantidade));
    setEditUnit(found.unidade);
    setEditObs(found.observacao ?? '');
    setEditPreco(
      found.preco_unitario_esboco !== null
        ? String(found.preco_unitario_esboco)
        : '',
    );
    setEditFonteCusto(found.nf_item_id ? 'nf' : 'fixo');
    setEditNfItemId(
      found.nf_item_id ? String(found.nf_item_id) : '',
    );
    setEditUnidadesPorEmbalagem(
      found.unidades_por_embalagem
        ? String(found.unidades_por_embalagem)
        : '',
    );
    setEditNfSearch('');
  }, [selectedItemData, items]);

  // ── Node drag → save position ───────────────────────────────────────────
  const handleNodeDragStop: NodeDragHandler = useCallback(
    (_evt, node) => {
      savePosition(node.id, node.position.x, node.position.y);
    },
    [savePosition],
  );

  // ── Node click → open detail panel ─────────────────────────────────────
  const handleNodeClick = useCallback(
    (_evt: React.MouseEvent, node: Node) => {
      const rawId = (node.data as Record<string, unknown>)._rawItemId;
      if (typeof rawId !== 'number') {
        setSelectedItemData(null);
        return;
      }
      const found = items.find((it) => it.id === rawId);
      if (found) {
        setSelectedItemData(found);
      }
    },
    [items],
  );

  // ── Auto-layout ─────────────────────────────────────────────────────────
  const handleAutoLayout = useCallback(() => {
    setNodes((prev) => {
      const laid = layoutGraph(prev, edges, 'LR');
      laid.forEach((n) => savePosition(n.id, n.position.x, n.position.y));
      return laid;
    });
    setTimeout(() => fitView({ padding: 0.12, duration: 400 }), 80);
  }, [edges, fitView, savePosition, setNodes]);

  // ── Reset add dialog ────────────────────────────────────────────────────
  const resetAddDialog = useCallback(() => {
    setNewTipo('embalagem');
    setNewEmbalagemId('');
    setNewEmbalagemOpen(false);
    setNewEmbalagemSearch('');
    setNewFonteCusto('nf');
    setNewNfItemId('');
    setNewNfOpen(false);
    setNewNfSearch('');
    setNewUnidadesPorEmbalagem('');
    setNewPrecoFixo('');
    setNewQty('1');
    setNewUnit('un');
    setNewObs('');
    setNewPrecoOutro('');
  }, []);

  // ── Add item ────────────────────────────────────────────────────────────
  const handleAddItem = useCallback(async () => {
    if (!cmvId) return;

    if (newTipo === 'embalagem') {
      if (!newEmbalagemId) {
        toast.error('Selecione uma embalagem.');
        return;
      }
      if (newFonteCusto === 'nf' && !newNfItemId) {
        toast.error('Selecione um item de NF ou mude para "Valor fixo".');
        return;
      }
      if (newFonteCusto === 'fixo' && !newPrecoFixo) {
        toast.error('Informe o valor unitário fixo da embalagem.');
        return;
      }
    } else {
      if (!newObs.trim()) {
        toast.error('Informe o nome do custo avulso.');
        return;
      }
    }

    setIsAddSaving(true);

    const payload: Record<string, unknown> = {
      cmv_id: cmvId,
      tipo: newTipo,
      quantidade: parseFloat(newQty) || 1,
      unidade: newUnit,
      ordem: items.length,
    };

    if (newTipo === 'embalagem') {
      payload.produto_master_id = parseInt(newEmbalagemId, 10);
      payload.nf_item_id =
        newFonteCusto === 'nf' && newNfItemId
          ? parseInt(newNfItemId, 10)
          : null;
      payload.unidades_por_embalagem =
        newFonteCusto === 'nf' && newUnidadesPorEmbalagem
          ? parseFloat(newUnidadesPorEmbalagem)
          : null;
      payload.preco_unitario_esboco =
        newFonteCusto === 'fixo' && newPrecoFixo
          ? parseFloat(newPrecoFixo)
          : null;
    } else {
      payload.observacao = newObs.trim();
      payload.preco_unitario_esboco = newPrecoOutro
        ? parseFloat(newPrecoOutro)
        : null;
    }

    const { error } = await supabase.from('cmv_itens').insert(payload);

    if (error) {
      toast.error(`Erro ao criar item: ${error.message}`);
    } else {
      toast.success('Item adicionado!');
      setIsAddOpen(false);
      resetAddDialog();
      await refetch();
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
    }
    setIsAddSaving(false);
  }, [
    cmvId,
    newTipo,
    newEmbalagemId,
    newFonteCusto,
    newNfItemId,
    newUnidadesPorEmbalagem,
    newPrecoFixo,
    newQty,
    newUnit,
    newObs,
    newPrecoOutro,
    items.length,
    refetch,
    queryClient,
    resetAddDialog,
  ]);

  // ── Save item ───────────────────────────────────────────────────────────
  const handleSaveItem = useCallback(async () => {
    if (!selectedItemData) return;
    setIsSaving(true);

    const updatePayload: Record<string, unknown> = {
      quantidade: parseFloat(editQty) || selectedItemData.quantidade,
      unidade: editUnit,
    };

    if (selectedItemData.tipo === 'embalagem') {
      updatePayload.nf_item_id =
        editFonteCusto === 'nf' && editNfItemId
          ? parseInt(editNfItemId, 10)
          : null;
      updatePayload.unidades_por_embalagem =
        editFonteCusto === 'nf' && editUnidadesPorEmbalagem
          ? parseFloat(editUnidadesPorEmbalagem)
          : null;
      updatePayload.preco_unitario_esboco =
        editFonteCusto === 'fixo' && editPreco
          ? parseFloat(editPreco)
          : null;
    } else {
      updatePayload.preco_unitario_esboco =
        editPreco !== '' ? parseFloat(editPreco) : null;
      updatePayload.observacao = editObs.trim() || null;
    }

    const { error } = await supabase
      .from('cmv_itens')
      .update(updatePayload)
      .eq('id', selectedItemData.id);

    if (error) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } else {
      toast.success('Item atualizado!');
      setSelectedItemData(null);
      await refetch();
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
    }
    setIsSaving(false);
  }, [
    selectedItemData,
    editQty,
    editUnit,
    editFonteCusto,
    editNfItemId,
    editUnidadesPorEmbalagem,
    editPreco,
    editObs,
    refetch,
    queryClient,
  ]);

  // ── Delete item ─────────────────────────────────────────────────────────
  const handleDeleteItem = useCallback(async () => {
    if (!selectedItemData) return;
    setIsDeleting(true);
    const { error } = await supabase
      .from('cmv_itens')
      .delete()
      .eq('id', selectedItemData.id);

    if (error) {
      toast.error(`Erro ao excluir: ${error.message}`);
    } else {
      toast.success('Item removido!');
      setSelectedItemData(null);
      await refetch();
      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
    }
    setIsDeleting(false);
  }, [selectedItemData, refetch, queryClient]);

  // ── Empty / loading states ──────────────────────────────────────────────
  if (!cmvId) {
    return (
      <div className="h-[100dvh] bg-white dark:bg-[#0A0A0A] flex flex-col items-center justify-center text-muted-foreground">
        <Calculator className="h-12 w-12 mb-4 text-[#57715B]" />
        <p className="text-sm mb-4">Nenhum CMV selecionado</p>
        <Button
          variant="outline"
          className="rounded-xl border-[#57715B]/20 bg-white/60 hover:bg-[#57715B]/10 text-[#57715B]"
          onClick={() => navigate('/financeiro/cmv')}
        >
          <ArrowLeft className="mr-2 h-4 w-4" />
          Voltar ao CMV
        </Button>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="h-[100dvh] bg-white dark:bg-[#0A0A0A] flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
      </div>
    );
  }

  if (!cmv) {
    return (
      <div className="h-[100dvh] bg-white dark:bg-[#0A0A0A] flex flex-col items-center justify-center text-muted-foreground">
        <p className="text-sm mb-4">CMV não encontrado.</p>
        <Button
          variant="outline"
          className="rounded-xl border-[#57715B]/20 bg-white/60 hover:bg-[#57715B]/10 text-[#57715B]"
          onClick={() => navigate('/financeiro/cmv')}
        >
          <ArrowLeft className="mr-2 h-4 w-4" />
          Voltar
        </Button>
      </div>
    );
  }

  // ── Selected NF label helpers ───────────────────────────────────────────
  const selectedNewNf = nfEmbalagemItems.find(
    (i) => String(i.id) === newNfItemId,
  );
  const selectedEditNf = nfEmbalagemItems.find(
    (i) => String(i.id) === editNfItemId,
  );

  // ── Render ──────────────────────────────────────────────────────────────
  return (
    <div className="fixed inset-0 bg-white dark:bg-[#0A0A0A] overflow-hidden">
      {/* Ambient blobs */}
      <div className="fixed top-[-10%] left-[-10%] w-[500px] h-[500px] bg-[#57715B]/5 blur-[80px] rounded-full pointer-events-none" />
      <div className="fixed top-[20%] right-[-5%] w-[400px] h-[400px] bg-[#C5A065]/5 blur-[80px] rounded-full pointer-events-none" />

      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        nodeTypes={nodeTypes}
        onNodeDragStop={handleNodeDragStop}
        onNodeClick={handleNodeClick}
        fitView
        proOptions={{ hideAttribution: true }}
        minZoom={0.2}
        maxZoom={2}
      >
        <Background
          variant={BackgroundVariant.Dots}
          color="#cbd5e1"
          gap={20}
        />
        <MiniMap
          className="!bg-white/90 !backdrop-blur !rounded-xl !shadow-md"
          nodeColor={() => '#57715B'}
          maskColor="rgba(0,0,0,0.6)"
        />

        {/* Toolbar topo esquerdo */}
        <Panel position="top-left">
          <div className="flex items-center gap-2 bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl px-3 py-2 shadow-xl">
            <Button
              variant="ghost"
              size="icon"
              aria-label="Voltar para lista de CMVs"
              className="h-7 w-7 text-muted-foreground hover:text-foreground"
              onClick={() => navigate('/financeiro/cmv')}
            >
              <ArrowLeft size={16} />
            </Button>
            <div className="w-px h-5 bg-[#57715B]/15" />
            <div className="flex items-center gap-2">
              <Calculator size={14} className="text-[#57715B]" />
              <span className="text-sm font-semibold truncate max-w-[180px]">
                {cmv.nome}
              </span>
              <span
                className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[cmv.status] ?? STATUS_COLORS.rascunho}`}
              >
                {cmv.status}
              </span>
            </div>
            <div className="w-px h-5 bg-[#57715B]/15" />
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs text-muted-foreground hover:text-foreground gap-1.5"
              onClick={handleAutoLayout}
            >
              <LayoutTemplate size={13} />
              <span className="hidden sm:inline">Auto-layout</span>
            </Button>
            <Button
              size="sm"
              className="h-7 text-xs rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white gap-1.5"
              onClick={() => setIsAddOpen(true)}
            >
              <Plus size={13} />
              <span className="hidden sm:inline">Adicionar</span>
            </Button>
          </div>
        </Panel>

        {/* Legenda top-right */}
        <Panel position="top-right">
          <div className="flex flex-col gap-1.5 bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl p-3 shadow-lg text-[10px] text-muted-foreground">
            <p className="text-[9px] font-bold uppercase tracking-widest mb-1">
              Legenda
            </p>
            <div className="flex items-center gap-1.5">
              <Calculator size={10} className="text-[#57715B]" />
              <span>CMV Central</span>
            </div>
            <div className="flex items-center gap-1.5">
              <ChefHat size={10} className="text-amber-500" />
              <span>Ficha Técnica</span>
            </div>
            <div className="flex items-center gap-1.5">
              <Package size={10} className="text-blue-400" />
              <span>Embalagem</span>
            </div>
            <div className="flex items-center gap-1.5">
              <DollarSign size={10} className="text-orange-400" />
              <span>Custo avulso</span>
            </div>
            <div className="flex items-center gap-1.5">
              <Wheat size={10} className="text-violet-400" />
