                      <Button
                        type="button"
                        size="sm"
                        onClick={() => setEditFonteCusto('fixo')}
                        className={cn(
                          'flex-1 rounded-xl text-xs gap-1.5',
                          editFonteCusto === 'fixo'
                            ? 'bg-[#57715B] hover:bg-[#465b49] text-white'
                            : 'border border-[#57715B]/20 bg-white/60 dark:bg-black/20 text-[#57715B] hover:bg-[#57715B]/10',
                        )}
                      >
                        <DollarSign size={12} />
                        Valor fixo
                      </Button>
                    </div>
                  </div>

                  {editFonteCusto === 'nf' ? (
                    <div className="space-y-3 rounded-xl border border-[#57715B]/10 p-3 bg-white/40 dark:bg-black/10">
                      <div>
                        <Label className="text-xs text-muted-foreground mb-1.5 block">
                          Item de NF
                        </Label>
                        <Popover
                          open={editNfOpen}
                          onOpenChange={setEditNfOpen}
                        >
                          <PopoverTrigger asChild>
                            <Button
                              variant="outline"
                              role="combobox"
                              className="w-full justify-between bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 hover:bg-[#57715B]/5 rounded-xl text-sm font-normal"
                            >
                              <span className="truncate">
                                {selectedEditNf?.nome_produto ??
                                  'Selecione o item de NF...'}
                              </span>
                              <ChevronsUpDown
                                size={14}
                                className="shrink-0 opacity-50"
                              />
                            </Button>
                          </PopoverTrigger>
                          <PopoverContent className="w-[360px] p-0 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-[#57715B]/10 rounded-xl">
                            <Command>
                              <CommandInput
                                placeholder="Buscar item..."
                                value={editNfSearch}
                                onValueChange={setEditNfSearch}
                              />
                              <CommandList>
                                <CommandEmpty>
                                  Nenhum item encontrado.
                                </CommandEmpty>
                                <CommandGroup>
                                  <ScrollArea className="h-52">
                                    {filteredEditNfItems.map((nfi) => (
                                      <CommandItem
                                        key={nfi.id}
                                        value={String(nfi.id)}
                                        onSelect={(v) => {
                                          setEditNfItemId(v);
                                          setEditNfOpen(false);
                                        }}
                                      >
                                        <Check
                                          size={12}
                                          className={cn(
                                            'mr-2 shrink-0',
                                            editNfItemId === String(nfi.id)
                                              ? 'opacity-100'
                                              : 'opacity-0',
                                          )}
                                        />
                                        <div className="min-w-0">
                                          <p className="text-xs font-medium truncate">
                                            {nfi.nome_produto}
                                          </p>
                                          <p className="text-[10px] text-muted-foreground truncate">
                                            {fmt(nfi.valor_unitario)} |{' '}
                                            {nfi.fornecedor} | #
                                            {nfi.numero_nota} |{' '}
                                            {fmtDate(nfi.data_nota)}
                                          </p>
                                        </div>
                                      </CommandItem>
                                    ))}
                                  </ScrollArea>
                                </CommandGroup>
                              </CommandList>
                            </Command>
                          </PopoverContent>
                        </Popover>
                      </div>

                      <div>
                        <Label className="text-xs text-muted-foreground">
                          Unidades por embalagem
                        </Label>
                        <Input
                          type="number"
                          className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                          placeholder="Ex: 200"
                          value={editUnidadesPorEmbalagem}
                          onChange={(e) =>
                            setEditUnidadesPorEmbalagem(e.target.value)
                          }
                        />
                        {editNfCustoHint !== null && (
                          <p className="text-[11px] text-[#57715B] mt-1">
                            Custo unitário ≈ {fmt(editNfCustoHint)}
                          </p>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div>
                      <Label className="text-xs text-muted-foreground">
                        Valor unitário (R$)
                      </Label>
                      <Input
                        type="number"
                        step="0.01"
                        className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                        placeholder="0,00"
                        value={editPreco}
                        onChange={(e) => setEditPreco(e.target.value)}
                      />
                    </div>
                  )}
                </>
              )}

              {selectedItemData.tipo === 'outro' && (
                <>
                  <div>
                    <Label className="text-xs text-muted-foreground">
                      Nome do custo
                    </Label>
                    <Input
                      className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                      placeholder="Ex: Frete, Overhead..."
                      value={editObs}
                      onChange={(e) => setEditObs(e.target.value)}
                    />
                  </div>
                  <div>
                    <Label className="text-xs text-muted-foreground">
                      Preço unitário (esboço)
                    </Label>
                    <Input
                      type="number"
                      step="0.01"
                      className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                      placeholder="0,00"
                      value={editPreco}
                      onChange={(e) => setEditPreco(e.target.value)}
                    />
                  </div>
                </>
              )}

              {/* Quantidade + Unidade */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs text-muted-foreground">
                    Quantidade
                  </Label>
                  <Input
                    type="number"
                    className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    value={editQty}
                    onChange={(e) => setEditQty(e.target.value)}
                  />
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">
                    Unidade
                  </Label>
                  <Input
                    className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    value={editUnit}
                    onChange={(e) => setEditUnit(e.target.value)}
                  />
                </div>
              </div>

              {selectedItemData.custo_calculado !== null && (
                <div className="pt-2 border-t border-[#57715B]/10">
                  <p className="text-xs text-muted-foreground">
                    Custo calculado
                  </p>
                  <p className="text-xl font-bold text-emerald-600 dark:text-emerald-400 tabular-nums">
                    {fmt(selectedItemData.custo_calculado)}
                  </p>
                </div>
              )}
            </div>
          )}

          <SheetFooter className="mt-6 flex gap-2">
            <Button
              variant="destructive"
              size="sm"
              className="flex-1 rounded-xl"
              onClick={handleDeleteItem}
              disabled={isDeleting || isSaving}
            >
              {isDeleting ? (
                <Loader2 size={14} className="animate-spin mr-1" />
              ) : (
                <Trash2 size={14} className="mr-1" />
              )}
              Excluir
            </Button>
            <Button
              size="sm"
              className="flex-1 rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={handleSaveItem}
              disabled={isSaving || isDeleting}
            >
              {isSaving ? (
                <Loader2 size={14} className="animate-spin mr-1" />
              ) : (
                <Save size={14} className="mr-1" />
              )}
              Salvar
            </Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>

      {/* ─── Add Item Dialog ─── */}
      <Dialog
        open={isAddOpen}
        onOpenChange={(o) => {
          setIsAddOpen(o);
          if (!o) resetAddDialog();
        }}
      >
        <DialogContent className="rounded-2xl border-white/40 dark:border-white/10 bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl max-h-[90vh] overflow-y-auto sm:max-w-[520px]">
          <DialogHeader>
            <DialogTitle>Adicionar Item de Custo</DialogTitle>
          </DialogHeader>

          <div className="space-y-5 py-2">
            {/* Tipo */}
            <div>
              <Label className="text-xs text-muted-foreground">
                Tipo de custo
              </Label>
              <Select
                value={newTipo}
                onValueChange={(v) => {
                  setNewTipo(v as TipoItem);
                  setNewEmbalagemId('');
                  setNewObs('');
                  setNewPrecoFixo('');
                  setNewPrecoOutro('');
                  setNewNfItemId('');
                  setNewUnit('un');
                  setNewQty('1');
                }}
              >
                <SelectTrigger className="mt-1 rounded-xl border-[#57715B]/20 bg-white/80 dark:bg-black/20">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-[#57715B]/10 bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl">
                  <SelectItem value="embalagem">
