                                      {emb.unidade_medida ?? 'un'}
                                    </span>
                                  )}
                                </CommandItem>
                              ))}
                            </ScrollArea>
                          </CommandGroup>
                        </CommandList>
                      </Command>
                    </PopoverContent>
                  </Popover>
                </div>

                {/* Fonte de custo toggle */}
                <div>
                  <Label className="text-xs text-muted-foreground mb-2 block">
                    Fonte de custo
                  </Label>
                  <div className="flex gap-2">
                    <Button
                      type="button"
                      size="sm"
                      onClick={() => setNewFonteCusto('nf')}
                      className={cn(
                        'flex-1 rounded-xl text-xs gap-1.5',
                        newFonteCusto === 'nf'
                          ? 'bg-[#57715B] hover:bg-[#465b49] text-white'
                          : 'border border-[#57715B]/20 bg-white/60 dark:bg-black/20 text-[#57715B] hover:bg-[#57715B]/10',
                      )}
                    >
                      <Receipt size={12} />
                      Por Nota Fiscal
                    </Button>
                    <Button
                      type="button"
                      size="sm"
                      onClick={() => setNewFonteCusto('fixo')}
                      className={cn(
                        'flex-1 rounded-xl text-xs gap-1.5',
                        newFonteCusto === 'fixo'
                          ? 'bg-[#57715B] hover:bg-[#465b49] text-white'
                          : 'border border-[#57715B]/20 bg-white/60 dark:bg-black/20 text-[#57715B] hover:bg-[#57715B]/10',
                      )}
                    >
                      <DollarSign size={12} />
                      Valor fixo
                    </Button>
                  </div>
                </div>

                {/* Por NF */}
                {newFonteCusto === 'nf' && (
                  <div className="space-y-3 rounded-xl border border-[#57715B]/10 p-3 bg-white/40 dark:bg-black/10">
                    <div>
                      <Label className="text-xs text-muted-foreground mb-1.5 block">
                        Item de NF{' '}
                        <span className="text-orange-500">*</span>
                      </Label>
                      <Popover
                        open={newNfOpen}
                        onOpenChange={setNewNfOpen}
                      >
                        <PopoverTrigger asChild>
                          <Button
                            variant="outline"
                            role="combobox"
                            className="w-full justify-between bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 hover:bg-[#57715B]/5 rounded-xl font-normal text-sm"
                          >
                            <span className="truncate">
                              {selectedNewNf?.nome_produto ??
                                'Selecione o item de NF...'}
                            </span>
                            <ChevronsUpDown
                              size={14}
                              className="shrink-0 opacity-50"
                            />
                          </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-[460px] p-0 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-[#57715B]/10 rounded-xl">
                          <Command>
                            <CommandInput
                              placeholder="Buscar item de nota..."
                              value={newNfSearch}
                              onValueChange={setNewNfSearch}
                            />
                            <CommandList>
                              <CommandEmpty>
                                Nenhum item encontrado.
                              </CommandEmpty>
                              <CommandGroup>
                                <ScrollArea className="h-52">
                                  {filteredNfItems.map((nfi) => (
                                    <CommandItem
                                      key={nfi.id}
                                      value={String(nfi.id)}
                                      onSelect={(v) => {
                                        setNewNfItemId(v);
                                        setNewNfOpen(false);
                                      }}
                                    >
                                      <Check
                                        size={12}
                                        className={cn(
                                          'mr-2 shrink-0',
                                          newNfItemId === String(nfi.id)
                                            ? 'opacity-100'
                                            : 'opacity-0',
                                        )}
                                      />
                                      <div className="min-w-0">
                                        <p className="text-xs font-medium truncate">
                                          {nfi.nome_produto}
                                        </p>
                                        <p className="text-[10px] text-muted-foreground truncate">
                                          {fmt(nfi.valor_unitario)} |{' '}
                                          {nfi.fornecedor} | #
                                          {nfi.numero_nota} |{' '}
                                          {fmtDate(nfi.data_nota)}
                                        </p>
                                      </div>
                                    </CommandItem>
                                  ))}
                                </ScrollArea>
                              </CommandGroup>
                            </CommandList>
                          </Command>
                        </PopoverContent>
                      </Popover>

                      {/* Aviso: sem NF mas embalagem tem preco_custo */}
                      {selectedEmbalagem?.preco_custo !== null &&
                        selectedEmbalagem?.preco_custo !== undefined &&
                        !newNfItemId && (
                          <p className="text-[11px] text-amber-600 dark:text-amber-400 mt-1.5">
                            Aviso: nenhuma NF selecionada — usará o preço de
                            cadastro ({fmt(selectedEmbalagem.preco_custo)}).
                          </p>
                        )}
                    </div>

                    <div>
                      <Label className="text-xs text-muted-foreground">
                        Unidades por embalagem
                      </Label>
                      <Input
                        type="number"
                        className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                        placeholder="Ex: 200 — unidades no pacote/caixa"
                        value={newUnidadesPorEmbalagem}
                        onChange={(e) =>
                          setNewUnidadesPorEmbalagem(e.target.value)
                        }
                      />
                      {nfCustoHint !== null && (
                        <p className="text-[11px] text-[#57715B] mt-1">
                          Custo unitário ≈ {fmt(nfCustoHint)}
                        </p>
                      )}
                    </div>
                  </div>
                )}

                {/* Valor fixo */}
                {newFonteCusto === 'fixo' && (
                  <div>
                    <Label className="text-xs text-muted-foreground">
                      Valor unitário (R$){' '}
                      <span className="text-orange-500">*</span>
                    </Label>
                    <Input
                      type="number"
                      step="0.01"
                      className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                      placeholder="0,00"
                      value={newPrecoFixo}
                      onChange={(e) => setNewPrecoFixo(e.target.value)}
                    />
                  </div>
                )}
              </>
            )}

            {/* ─── CUSTO AVULSO ─── */}
            {newTipo === 'outro' && (
              <>
                <div>
                  <Label className="text-xs text-muted-foreground">
                    Nome do custo{' '}
                    <span className="text-orange-500">*</span>
                  </Label>
                  <Input
                    className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    placeholder="Ex: Frete, Overhead, Gás..."
                    value={newObs}
                    onChange={(e) => setNewObs(e.target.value)}
                  />
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">
                    Preço unitário (R$)
                  </Label>
                  <Input
                    type="number"
                    step="0.01"
                    className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    placeholder="0,00"
                    value={newPrecoOutro}
                    onChange={(e) => setNewPrecoOutro(e.target.value)}
                  />
                </div>
              </>
            )}

            {/* Quantidade + Unidade */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs text-muted-foreground">
                  Quantidade
                </Label>
                <Input
                  type="number"
                  className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  value={newQty}
                  onChange={(e) => setNewQty(e.target.value)}
                />
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">
                  Unidade
                </Label>
                <Input
                  className="mt-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  placeholder="un, kg, cx..."
                  value={newUnit}
                  onChange={(e) => setNewUnit(e.target.value)}
                />
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              className="rounded-xl border-[#57715B]/20 bg-white/60 hover:bg-[#57715B]/10 text-[#57715B]"
              onClick={() => {
                setIsAddOpen(false);
                resetAddDialog();
              }}
            >
              Cancelar
            </Button>
            <Button
              className="rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={handleAddItem}
              disabled={
                isAddSaving ||
                (newTipo === 'embalagem' && !newEmbalagemId) ||
                (newTipo === 'outro' && !newObs.trim())
              }
            >
              {isAddSaving ? (
                <Loader2 size={14} className="animate-spin mr-1" />
              ) : (
                <Plus size={14} className="mr-1" />
              )}
              Adicionar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ---------------------------------------------------------------------------
// PUBLIC EXPORT — ReactFlowProvider wrapper
// ---------------------------------------------------------------------------

export default function CmvConfiguratorPage() {
  return (
    <ReactFlowProvider>
      <CmvConfiguratorInner />
    </ReactFlowProvider>
  );
}
